wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

/// Key within the `subscriptions` store holding newline-separated feed URLs.
const SUBSCRIPTIONS_KEY: &str = "urls";

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let urls = match state_read::get(SUBSCRIPTIONS_KEY) {
            Some(raw) => parse_urls(&raw),
            None => Vec::new(),
        };
        SubscriptionList { urls }
    }
}

/// Split the stored value into URLs: one per line, trimmed, blanks dropped.
fn parse_urls(raw: &str) -> Vec<String> {
    raw.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(String::from)
        .collect()
}

export!(Node);
